                var pcgStat = Bench.Time(() => pcgJob.Run());
                sb.AppendLine(LargeSparseFmt.Row("float", sz, "PCG-Jacobi", pcgStat, Res(in A, in xp, in b), (int)oi[1], (int)oi[0]));
                var xs = new floatN(N, Allocator.Persistent);
                var ssorR = new floatN(N, Allocator.Persistent); var ssorP = new floatN(N, Allocator.Persistent); var ssorAp = new floatN(N, Allocator.Persistent); var ssorZ = new floatN(N, Allocator.Persistent);
                var ssorJob = new SpPcgSSORJobFloat { A = A, M = ssor, b = b, x = xs, r = ssorR, p = ssorP, Ap = ssorAp, z = ssorZ, K = K, outInfo = oi };
                var ssorStat = Bench.Time(() => ssorJob.Run());
                sb.AppendLine(LargeSparseFmt.Row("float", sz, "PCG-SSOR", ssorStat, Res(in A, in xs, in b), (int)oi[1], (int)oi[0]));
                var xm = new floatN(N, Allocator.Persistent);
                var mrY = new floatN(N, Allocator.Persistent); var mrR1 = new floatN(N, Allocator.Persistent); var mrR2 = new floatN(N, Allocator.Persistent);
                var mrV = new floatN(N, Allocator.Persistent); var mrW = new floatN(N, Allocator.Persistent); var mrW1 = new floatN(N, Allocator.Persistent); var mrW2 = new floatN(N, Allocator.Persistent);
                var mrJob = new SpMinresJobFloat { A = A, b = b, x = xm, y = mrY, r1 = mrR1, r2 = mrR2, v = mrV, w = mrW, w1 = mrW1, w2 = mrW2, K = K, outInfo = oi };
                var mrStat = Bench.Time(() => mrJob.Run());
                sb.AppendLine(LargeSparseFmt.Row("float", sz, "MINRES", mrStat, Res(in A, in xm, in b), (int)oi[1], (int)oi[0]));

                floatN xc1 = default, cgConvR = default, cgConvP = default, cgConvAp = default;
                floatN xc2 = default, pcgConvR = default, pcgConvP = default, pcgConvAp = default, pcgConvZ = default;
                floatN xc3 = default, ssorConvR = default, ssorConvP = default, ssorConvAp = default, ssorConvZ = default;
                bool ranConv = N == Ns[Ns.Length - 1];
                if (ranConv)
                {
                    float convTol = Consts.floatSqrtEps;
                    int convMaxIter = 8 * N;

                    xc1 = new floatN(N, Allocator.Persistent);
                    cgConvR = new floatN(N, Allocator.Persistent); cgConvP = new floatN(N, Allocator.Persistent); cgConvAp = new floatN(N, Allocator.Persistent);
                    var cgConvJob = new SpCgJobFloat { A = A, b = b, x = xc1, r = cgConvR, p = cgConvP, Ap = cgConvAp, K = convMaxIter, tol = convTol, outInfo = oi };
                    var cgConvStat = Bench.Time(() => cgConvJob.Run());
                    sb.AppendLine(LargeSparseFmt.Row("float", sz, "CG@tol", cgConvStat, Res(in A, in xc1, in b), (int)oi[1], (int)oi[0]));

                    xc2 = new floatN(N, Allocator.Persistent);
                    pcgConvR = new floatN(N, Allocator.Persistent); pcgConvP = new floatN(N, Allocator.Persistent); pcgConvAp = new floatN(N, Allocator.Persistent); pcgConvZ = new floatN(N, Allocator.Persistent);
                    var pcgConvJob = new SpPcgJobFloat { A = A, M = M, b = b, x = xc2, r = pcgConvR, p = pcgConvP, Ap = pcgConvAp, z = pcgConvZ, K = convMaxIter, tol = convTol, outInfo = oi };
                    var pcgConvStat = Bench.Time(() => pcgConvJob.Run());
                    sb.AppendLine(LargeSparseFmt.Row("float", sz, "PCG-Jacobi@tol", pcgConvStat, Res(in A, in xc2, in b), (int)oi[1], (int)oi[0]));

                    xc3 = new floatN(N, Allocator.Persistent);
                    ssorConvR = new floatN(N, Allocator.Persistent); ssorConvP = new floatN(N, Allocator.Persistent); ssorConvAp = new floatN(N, Allocator.Persistent); ssorConvZ = new floatN(N, Allocator.Persistent);
                    var ssorConvJob = new SpPcgSSORJobFloat { A = A, M = ssor, b = b, x = xc3, r = ssorConvR, p = ssorConvP, Ap = ssorConvAp, z = ssorConvZ, K = convMaxIter, tol = convTol, outInfo = oi };
                    var ssorConvStat = Bench.Time(() => ssorConvJob.Run());
                    sb.AppendLine(LargeSparseFmt.Row("float", sz, "PCG-SSOR@tol", ssorConvStat, Res(in A, in xc3, in b), (int)oi[1], (int)oi[0]));
                }

                A.Dispose(); M.Dispose(); ssor.Dispose(); xKnown.Dispose(); b.Dispose();
                x.Dispose(); cgR.Dispose(); cgP.Dispose(); cgAp.Dispose();
                xp.Dispose(); pcgR.Dispose(); pcgP.Dispose(); pcgAp.Dispose(); pcgZ.Dispose();
                xs.Dispose(); ssorR.Dispose(); ssorP.Dispose(); ssorAp.Dispose(); ssorZ.Dispose();
                xm.Dispose(); mrY.Dispose(); mrR1.Dispose(); mrR2.Dispose(); mrV.Dispose(); mrW.Dispose(); mrW1.Dispose(); mrW2.Dispose();
                if (ranConv)
                {
                    xc1.Dispose(); cgConvR.Dispose(); cgConvP.Dispose(); cgConvAp.Dispose();
                    xc2.Dispose(); pcgConvR.Dispose(); pcgConvP.Dispose(); pcgConvAp.Dispose(); pcgConvZ.Dispose();
                    xc3.Dispose(); ssorConvR.Dispose(); ssorConvP.Dispose(); ssorConvAp.Dispose(); ssorConvZ.Dispose();
                }
            }

            oi.Dispose();
        }

        static void BenchEigenFloat(StringBuilder sb, int BR, int[] Ns, float density, int lanczosSteps)
        {
            foreach (int N in Ns)
            {
                int nb = N / BR;
                var A = floatGallery.floatRandomSparseSPD(nb, BR, density, 0x5A17u, Allocator.Persistent);
                string sz = N.ToString();
                var outInfo = new NativeArray<double>(3, Allocator.Persistent);

                var lws = new floatLanczosCache(N, lanczosSteps, Allocator.Persistent);
                var lvals = new floatN(lanczosSteps, Allocator.Persistent);
                var lanJob = new SpLanczosJobFloat { A = A, ws = lws, vals = lvals, steps = lanczosSteps, outInfo = outInfo };
                var lanStat = Bench.Time(() => lanJob.Run());
                sb.AppendLine(LargeSparseFmt.EigRow("float", sz, "Lanczos s=" + lanczosSteps, lanStat, new[] { outInfo[0], outInfo[1], outInfo[2] }));

                outInfo.Dispose();
                A.Dispose(); lws.Dispose(); lvals.Dispose();
            }
        }

        // Rows: none/guard0 -> blockJac/guard0 -> SSOR/guard0 -> blockJac/guardG, showing both
        // levers (precond alone, then precond+guard stacking). Every row carries wall-clock
        // (Bench.Time, 1 warmup + 4 timed) alongside iterations -- see SpLobpcgJobFloat's comment
        // for why ws.X must be re-zeroed every Execute() for that to be a fair repeated measurement.
        static void BenchLobpcgFloat(StringBuilder sb, int[] eigGrids, int lobpcgK, int lobpcgGuard, int lobpcgMaxIter)
        {
            foreach (int g in eigGrids)
            {
                int n = g * g;
                var A = floatGallery.floatLaplacian2D(g, g, Allocator.Persistent);
                var M = new floatBlockJacobi(in A, Allocator.Persistent);
                var ssor = new floatSSOR(in A, Allocator.Persistent);
                string grid = g + "x" + g + "(" + n + ")";
                var oi = new NativeArray<double>(5, Allocator.Persistent);
                float tol = Consts.floatSqrtEps;

                var noneWs = new floatLOBPCGCache(n, lobpcgK, Allocator.Persistent);
                var noneJob = new SpLobpcgJobFloat { A = A, ws = noneWs, k = lobpcgK, tol = tol, maxIter = lobpcgMaxIter, outInfo = oi };
                var noneStat = Bench.Time(() => noneJob.Run());
                LargeSparseFmt.LobRow(sb, "float", grid, "none", 0, noneStat, LargeSparseFmt.Snap(oi));

                var jacWs = new floatLOBPCGCache(n, lobpcgK, Allocator.Persistent);
                var jacJob = new SpLobpcgPrecJobFloat { A = A, M = M, ws = jacWs, k = lobpcgK, tol = tol, maxIter = lobpcgMaxIter, outInfo = oi };
                var jacStat = Bench.Time(() => jacJob.Run());
                LargeSparseFmt.LobRow(sb, "float", grid, "blockJac", 0, jacStat, LargeSparseFmt.Snap(oi));

                var ssorWs = new floatLOBPCGCache(n, lobpcgK, Allocator.Persistent);
                var ssorJob = new SpLobpcgSSORJobFloat { A = A, M = ssor, ws = ssorWs, k = lobpcgK, tol = tol, maxIter = lobpcgMaxIter, outInfo = oi };
                var ssorStat = Bench.Time(() => ssorJob.Run());
                LargeSparseFmt.LobRow(sb, "float", grid, "SSOR", 0, ssorStat, LargeSparseFmt.Snap(oi));

                var jacGuardWs = new floatLOBPCGCache(n, lobpcgK + lobpcgGuard, Allocator.Persistent);
                var jacGuardJob = new SpLobpcgPrecJobFloat { A = A, M = M, ws = jacGuardWs, k = lobpcgK, tol = tol, maxIter = lobpcgMaxIter, outInfo = oi };
                var jacGuardStat = Bench.Time(() => jacGuardJob.Run());
                LargeSparseFmt.LobRow(sb, "float", grid, "blockJac", lobpcgGuard, jacGuardStat, LargeSparseFmt.Snap(oi));

                oi.Dispose();
                A.Dispose(); M.Dispose(); ssor.Dispose();
                noneWs.Dispose(); jacWs.Dispose(); ssorWs.Dispose(); jacGuardWs.Dispose();
            }
        }
    }
}
